import React, { useState, useCallback, useRef, useEffect } from 'react';
import { MathFormula } from '../MathFormula';
import { AngleType } from '../../types';

export const AngleExplorer: React.FC = () => {
  const [angle, setAngle] = useState(45);
  const containerRef = useRef<SVGSVGElement>(null);

  const getAngleType = (deg: number): AngleType => {
    if (deg === 0) return 'agudo';
    if (deg < 90) return 'agudo';
    if (deg === 90) return 'recto';
    if (deg < 180) return 'obtuso';
    if (deg === 180) return 'llano';
    if (deg < 360) return 'reflejo';
    return 'completo';
  };

  const getNarrative = (type: AngleType) => {
    switch (type) {
      case 'agudo': return 'Es pequeño, agudo... como un punto de enfoque inicial.';
      case 'recto': return 'Firme, equilibrado, la base de toda construcción estable.';
      case 'obtuso': return 'Abierto, acogedor, explorando más allá de lo inmediato.';
      case 'llano': return 'Una dirección opuesta, pero en total armonía y equilibrio.';
      case 'reflejo': return 'Un giro profundo, mirando hacia el interior de la vuelta.';
      case 'completo': return 'Has vuelto al origen, habiendo explorado todo el horizonte.';
      default: return '';
    }
  };

  const handleMouseMove = useCallback((e: React.MouseEvent | React.TouchEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;

    let clientX, clientY;
    if ('touches' in e) {
        clientX = e.touches[0].clientX;
        clientY = e.touches[0].clientY;
    } else {
        clientX = e.clientX;
        clientY = e.clientY;
    }

    const x = clientX - rect.left - centerX;
    const y = clientY - rect.top - centerY;

    let deg = Math.atan2(-y, x) * (180 / Math.PI);
    if (deg < 0) deg += 360;
    setAngle(Math.round(deg));
  }, []);

  const type = getAngleType(angle);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-center">
      <div className="flex flex-col items-center">
        <svg 
          ref={containerRef}
          viewBox="0 0 400 400" 
          className="w-full max-w-[400px] aspect-square cursor-crosshair touch-none"
          onMouseMove={handleMouseMove}
          onTouchMove={handleMouseMove}
        >
          {/* Background Grid */}
          <line x1="0" y1="200" x2="400" y2="200" stroke="rgba(255,255,255,0.05)" strokeWidth="1" />
          <line x1="200" y1="0" x2="200" y2="400" stroke="rgba(255,255,255,0.05)" strokeWidth="1" />

          {/* Angle Arc */}
          <path 
            d={`M 200 200 L 280 200 A 80 80 0 ${angle > 180 ? 1 : 0} 0 ${200 + 80 * Math.cos(-angle * Math.PI / 180)} ${200 + 80 * Math.sin(-angle * Math.PI / 180)} Z`}
            fill="rgba(99, 102, 241, 0.2)"
            stroke="rgb(99, 102, 241)"
            strokeWidth="2"
          />

          {/* Fixed Ray */}
          <line x1="200" y1="200" x2="380" y2="200" stroke="white" strokeWidth="4" strokeLinecap="round" />

          {/* Moving Ray */}
          <line 
            x1="200" y1="200" 
            x2={200 + 180 * Math.cos(-angle * Math.PI / 180)} 
            y2={200 + 180 * Math.sin(-angle * Math.PI / 180)} 
            stroke="rgb(168, 85, 247)" 
            strokeWidth="4" 
            strokeLinecap="round"
          />

          <circle cx="200" cy="200" r="6" fill="white" />
        </svg>
        <p className="mt-4 text-slate-400 text-sm italic">Mueve el rayo púrpura para explorar</p>
      </div>

      <div className="space-y-6">
        <div className="glass p-8 rounded-3xl">
          <div className="flex items-end gap-3 mb-6">
             <span className="text-6xl font-bold text-white tracking-tighter">{angle}°</span>
             <span className="text-xl text-indigo-400 font-medium mb-2 uppercase tracking-widest">{type}</span>
          </div>

          <div className="space-y-4">
            <p className="text-lg text-slate-200 leading-relaxed">
              {getNarrative(type)}
            </p>

            <div className="p-4 bg-white/5 rounded-xl border border-white/10">
              <h4 className="text-sm font-semibold text-indigo-300 mb-1 uppercase tracking-wider">Concepto:</h4>
              <p className="text-sm text-slate-400">
                {type === 'agudo' && "Ángulo menor a 90°. Representa sutileza y enfoque."}
                {type === 'recto' && "Exactamente 90°. La perpendicularidad absoluta."}
                {type === 'obtuso' && "Mayor a 90° pero menor a 180°. Apertura y amplitud."}
                {type === 'llano' && "Exactamente 180°. La línea recta del horizonte."}
                {type === 'reflejo' && "Mayor a 180°. Una vuelta que se mira a sí misma."}
                {type === 'completo' && "360°. El ciclo perfecto que vuelve al inicio."}
              </p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { MathFormula } from '../MathFormula';

export const RadianVisualizer: React.FC = () => {
  const [progress, setProgress] = useState(0);
  const radius = 100;

  // Progress goes from 0 to 1 (which means angle = 1 rad)
  // or more to show multiple radians
  const maxRadian = Math.PI * 2;
  const currentAngle = progress * maxRadian;

  return (
    <div className="space-y-12">
      <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
        <div className="relative flex justify-center">
           <svg viewBox="0 0 300 300" className="w-full max-w-[300px]">
             {/* Main Circle */}
             <circle cx="150" cy="150" r={radius} fill="none" stroke="rgba(255,255,255,0.1)" strokeWidth="2" />

             {/* Radius Line */}
             <line x1="150" y1="150" x2={150 + radius} y2="150" stroke="white" strokeWidth="3" />

             {/* The Arc */}
             <path 
               d={`M ${150 + radius} 150 A ${radius} ${radius} 0 ${currentAngle > Math.PI ? 1 : 0} 0 ${150 + radius * Math.cos(-currentAngle)} ${150 + radius * Math.sin(-currentAngle)}`}
               fill="none"
               stroke={Math.abs(currentAngle - 1) < 0.05 ? "rgb(52, 211, 153)" : "rgb(99, 102, 241)"}
               strokeWidth="6"
               strokeLinecap="round"
               className="transition-colors duration-300"
             />

             {/* Dynamic Indicator */}
             {Math.abs(currentAngle - 1) < 0.05 && (
               <g>
                 <text x="180" y="130" fill="rgb(52, 211, 153)" className="text-xs font-bold animate-pulse">¡ARCO = RADIO!</text>
                 <text x="180" y="145" fill="rgb(52, 211, 153)" className="text-xs font-bold">1 RADIÁN</text>
               </g>
             )}
           </svg>
        </div>

        <div className="space-y-6">
          <div className="glass p-6 rounded-2xl">
            <h4 className="text-xl font-bold text-white mb-4">Control de Giro</h4>
            <input 
              type="range" 
              min="0" 
              max="1" 
              step="0.001" 
              value={progress} 
              onChange={(e) => setProgress(parseFloat(e.target.value))}
              className="w-full h-2 bg-slate-700 rounded-lg appearance-none cursor-pointer accent-indigo-500"
            />
            <div className="flex justify-between mt-2 text-xs text-slate-400 uppercase tracking-tighter">
              <span>0 Rad</span>
              <span>1 Vuelta (2π Rad)</span>
            </div>
          </div>

          <div className="glass p-6 rounded-2xl border-l-4 border-emerald-500">
             <p className="text-slate-200">
               "Mira cómo el arco crece. Cuando la longitud de ese arco azul es exactamente igual a la longitud del radio blanco... 
               <span className="text-emerald-400 font-bold"> ¡Eso es un radián!</span>"
             </p>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <div className="glass p-8 rounded-3xl flex flex-col justify-center items-center text-center">
          <MathFormula formula="\pi \text{ rad} = 180^\circ" block />
          <p className="text-slate-400 mt-4">Media vuelta a la circunferencia es el valor sagrado de Pi.</p>
        </div>
        <div className="glass p-8 rounded-3xl flex flex-col justify-center items-center text-center">
          <MathFormula formula="2\pi \text{ rad} = 360^\circ" block />
          <p className="text-slate-400 mt-4">La plenitud del círculo completo.</p>
        </div>
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { MathFormula } from '../MathFormula';

export const Converter: React.FC = () => {
  const [deg, setDeg] = useState('90');
  const [rad, setRad] = useState('π/2');

  const degToRadSteps = (d: string) => {
    const val = parseFloat(d) || 0;
    const fraction = val / 180;
    const gcd = (a: number, b: number): number => b ? gcd(b, a % b) : a;
    const common = gcd(val, 180);
    const num = val / common;
    const den = 180 / common;

    return {
      simplified: `${num === 1 ? '' : num}π / ${den}`,
      decimal: (val * Math.PI / 180).toFixed(4)
    };
  };

  const steps = degToRadSteps(deg);

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
      <div className="glass p-8 rounded-3xl space-y-6">
        <h3 className="text-xl font-bold text-white border-b border-white/10 pb-4">De Grados a Radianes</h3>
        <div className="space-y-4">
          <label className="block text-sm text-slate-400">Ingresa grados:</label>
          <input 
            type="number" 
            value={deg} 
            onChange={(e) => setDeg(e.target.value)}
            className="w-full bg-slate-900/50 border border-indigo-500/30 rounded-xl p-4 text-2xl font-bold text-white focus:ring-2 focus:ring-indigo-500 outline-none"
          />
        </div>

        <div className="bg-white/5 p-6 rounded-2xl space-y-4">
          <p className="text-indigo-300 text-sm font-semibold uppercase tracking-widest">Procedimiento:</p>
          <div className="flex flex-col gap-4">
             <MathFormula formula={`${deg}^\circ \times \frac{\pi}{180^\circ}`} block />
             <div className="flex items-center gap-4 text-emerald-400">
               <span className="text-xs uppercase font-bold">Resultado:</span>
               <MathFormula formula={steps.simplified} />
             </div>
             <div className="text-slate-500 text-xs">
               Valor decimal ≈ {steps.decimal} rad
             </div>
          </div>
        </div>
      </div>

      <div className="glass p-8 rounded-3xl space-y-6">
        <h3 className="text-xl font-bold text-white border-b border-white/10 pb-4">De Radianes a Grados</h3>
        <p className="text-slate-400 text-sm italic">"Próximamente... En esta versión, enfócate en transformar grados. La matemática es paciencia."</p>
        <div className="opacity-40 pointer-events-none grayscale">
          <div className="space-y-4">
            <label className="block text-sm text-slate-400">Ingresa radianes (ej. π/2):</label>
            <input 
              disabled
              type="text" 
              value={rad}
              className="w-full bg-slate-900/50 border border-white/10 rounded-xl p-4 text-2xl font-bold text-white"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

