interface MathFormulaProps {
  formula: string;
  block?: boolean;
}

export const MathFormula: React.FC<MathFormulaProps> = ({ formula, block }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (containerRef.current) {
      // KaTeX throws an error if it detects Quirks Mode (document.compatMode !== "CSS1Compat")
      // We've ensured index.html has a proper DOCTYPE, but we wrap this in a try-catch for robustness.
      try {
        katex.render(formula, containerRef.current, {
          throwOnError: false,
          displayMode: block,
        });
      } catch (error) {
        console.error("KaTeX rendering error:", error);
        containerRef.current.textContent = formula;
      }
    }
  }, [formula, block]);

  return <span ref={containerRef} className="math-font inline-block" />;
};

import React, { useEffect, useRef } from 'react';
import katex from 'katex';

interface MathFormulaProps {
  formula: string;
  block?: boolean;
}

export const MathFormula: React.FC<MathFormulaProps> = ({ formula, block }) => {
  const containerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (containerRef.current) {
      // Ensure the browser is in Standards Mode. document.compatMode should be "CSS1Compat".
      // We fixed the DOCTYPE in index.html, but we catch errors here to prevent app crashes.
      try {
        katex.render(formula, containerRef.current, {
          throwOnError: false,
          displayMode: block,
          trust: true,
          strict: false
        });
      } catch (error) {
        console.warn("KaTeX rendering error (possibly Quirks Mode):", error);
        // Fallback: show the raw LaTeX string if rendering fails
        containerRef.current.textContent = formula;
      }
    }
  }, [formula, block]);

  return <span ref={containerRef} className="math-font inline-block" />;
};

