import React, { useState, useCallback, useRef } from 'react';
import { AngleType } from '../../types';

export const AngleExplorer: React.FC = () => {
  const [angle, setAngle] = useState(45);
  const containerRef = useRef<SVGSVGElement>(null);

  const getAngleType = (deg: number): AngleType => {
    if (deg === 0) return 'nulo';
    if (deg < 90) return 'agudo';
    if (deg === 90) return 'recto';
    if (deg < 180) return 'obtuso';
    if (deg === 180) return 'llano';
    if (deg < 360) return 'reflejo';
    return 'completo';
  };

  const getNarrative = (type: AngleType) => {
    switch (type) {
      case 'nulo': return 'Mide exactamente 0°. No hay apertura, los lados coinciden.';
      case 'agudo': return 'Mide más de 0° y menos de 90°. Es sutil y agudo.';
      case 'recto': return 'Mide exactamente 90°. Sus lados son perpendiculares.';
      case 'obtuso': return 'Mide más de 90° y menos de 180°. Una apertura amplia.';
      case 'llano': return 'Mide exactamente 180°. Una línea recta perfecta.';
      case 'reflejo': return 'Mide más de 180° y menos de 360°. Un giro hacia el exterior.';
      case 'completo': return 'Mide exactamente 360°. Has completado el ciclo.';
      default: return '';
    }
  };

  const handleInteraction = useCallback((e: React.MouseEvent | React.TouchEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;

    let clientX, clientY;
    if ('touches' in e) {
        clientX = e.touches[0].clientX;
        clientY = e.touches[0].clientY;
    } else {
        clientX = e.clientX;
        clientY = e.clientY;
    }

    const x = clientX - rect.left - centerX;
    const y = clientY - rect.top - centerY;

    let deg = Math.atan2(-y, x) * (180 / Math.PI);
    if (deg < 0) deg += 360;
    setAngle(Math.round(deg));
  }, []);

  const type = getAngleType(angle);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-center">
      <div className="flex flex-col items-center relative">
        <svg 
          ref={containerRef}
          viewBox="0 0 400 400" 
          className="w-full max-w-[420px] aspect-square cursor-crosshair touch-none select-none"
          onMouseMove={(e) => e.buttons === 1 && handleInteraction(e)}
          onMouseDown={handleInteraction}
          onTouchMove={handleInteraction}
        >
          <defs>
            <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="9" refY="3.5" orient="auto">
              <polygon points="0 0, 10 3.5, 0 7" fill="currentColor" />
            </marker>
          </defs>

          {/* Transportador (Background Protractor) */}
          <circle cx="200" cy="200" r="180" fill="rgba(255,255,255,0.03)" stroke="rgba(255,255,255,0.1)" strokeWidth="1" />
          {[...Array(36)].map((_, i) => {
            const deg = i * 10;
            const rad = deg * Math.PI / 180;
            const x1 = 200 + 170 * Math.cos(rad);
            const y1 = 200 - 170 * Math.sin(rad);
            const x2 = 200 + 180 * Math.cos(rad);
            const y2 = 200 - 180 * Math.sin(rad);
            return (
              <g key={i}>
                <line x1={x1} y1={y1} x2={x2} y2={y2} stroke="rgba(255,255,255,0.2)" strokeWidth="1" />
                <text 
                  x={200 + 155 * Math.cos(rad)} 
                  y={200 - 155 * Math.sin(rad)} 
                  fill="rgba(255,255,255,0.3)" 
                  fontSize="8" 
                  textAnchor="middle" 
                  dominantBaseline="middle"
                  className="math-font"
                >
                  {deg}
                </text>
              </g>
            );
          })}

          {/* Area de Angulo */}
          <path 
            d={`M 200 200 L 280 200 A 80 80 0 ${angle > 180 ? 1 : 0} 0 ${200 + 80 * Math.cos(-angle * Math.PI / 180)} ${200 + 80 * Math.sin(-angle * Math.PI / 180)} Z`}
            fill="rgba(99, 102, 241, 0.25)"
            stroke="rgb(99, 102, 241)"
            strokeWidth="1"
          />

          {/* Rayo Fijo (Lado Inicial) */}
          <line x1="200" y1="200" x2="390" y2="200" stroke="white" strokeWidth="3" markerEnd="url(#arrowhead)" className="text-white" />

          {/* Rayo Movil (Lado Terminal) */}
          <line 
            x1="200" y1="200" 
            x2={200 + 190 * Math.cos(-angle * Math.PI / 180)} 
            y2={200 + 190 * Math.sin(-angle * Math.PI / 180)} 
            stroke="rgb(168, 85, 247)" 
            strokeWidth="4" 
            markerEnd="url(#arrowhead)"
            className="text-purple-400"
          />

          <circle cx="200" cy="200" r="5" fill="white" />
        </svg>
        <p className="mt-6 text-slate-400 text-sm font-medium animate-pulse">Haz clic y arrastra para mover el ángulo</p>
      </div>

      <div className="space-y-6">
        <div className="glass p-8 rounded-3xl shadow-2xl border-indigo-500/20">
          <div className="flex flex-col gap-1 mb-6">
             <span className="text-7xl font-black text-white tracking-tighter">{angle}°</span>
             <span className="text-xl text-indigo-400 font-bold uppercase tracking-[0.2em]">{type}</span>
          </div>

          <div className="space-y-6">
            <p className="text-xl text-slate-200 leading-relaxed font-light italic">
              "{getNarrative(type)}"
            </p>

            <div className="p-5 bg-indigo-500/5 rounded-2xl border border-indigo-500/10">
              <h4 className="text-xs font-bold text-indigo-400 mb-2 uppercase tracking-widest">Definición Matemática:</h4>
              <ul className="text-sm text-slate-300 space-y-2 list-disc pl-4">
                {type === 'nulo' && <li>θ = 0°</li>}
                {type === 'agudo' && <li>0° &lt; θ &lt; 90°</li>}
                {type === 'recto' && <li>θ = 90°</li>}
                {type === 'obtuso' && <li>90° &lt; θ &lt; 180°</li>}
                {type === 'llano' && <li>θ = 180°</li>}
                {type === 'reflejo' && <li>180° &lt; θ &lt; 360°</li>}
                {type === 'completo' && <li>θ = 360°</li>}
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

