import React, { useState, useCallback, useRef } from 'react';
import { AngleType } from '../../types';

export const AngleExplorer: React.FC = () => {
  const [angle, setAngle] = useState(45);
  const containerRef = useRef<SVGSVGElement>(null);

  const getAngleType = (deg: number): AngleType => {
    if (deg === 0) return 'nulo';
    if (deg < 90) return 'agudo';
    if (deg === 90) return 'recto';
    if (deg < 180) return 'obtuso';
    if (deg === 180) return 'llano';
    if (deg < 360) return 'reflejo';
    return 'completo';
  };

  const getNarrative = (type: AngleType) => {
    switch (type) {
      case 'nulo': return 'Mide exactamente 0°. No hay apertura, los lados coinciden.';
      case 'agudo': return 'Mide más de 0° y menos de 90°. Es sutil y agudo.';
      case 'recto': return 'Mide exactamente 90°. Sus lados son perpendiculares.';
      case 'obtuso': return 'Mide más de 90° y menos de 180°. Una apertura amplia.';
      case 'llano': return 'Mide exactamente 180°. Una línea recta perfecta.';
      case 'reflejo': return 'Mide más de 180° y menos de 360°. Un giro hacia el exterior.';
      case 'completo': return 'Mide exactamente 360°. Has completado el ciclo.';
      default: return '';
    }
  };

  const handleInteraction = useCallback((e: React.MouseEvent | React.TouchEvent) => {
    if (!containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const centerX = rect.width / 2;
    const centerY = rect.height / 2;

    let clientX, clientY;
    if ('touches' in e) {
        clientX = e.touches[0].clientX;
        clientY = e.touches[0].clientY;
    } else {
        clientX = e.clientX;
        clientY = e.clientY;
    }

    const x = clientX - rect.left - centerX;
    const y = clientY - rect.top - centerY;

    let deg = Math.atan2(-y, x) * (180 / Math.PI);
    if (deg < 0) deg += 360;
    setAngle(Math.round(deg));
  }, []);

  const type = getAngleType(angle);

  return (
    <div className="grid grid-cols-1 lg:grid-cols-2 gap-8 items-center bg-white p-8 rounded-[2rem] shadow-sm">
      <div className="flex flex-col items-center relative">
        <svg 
          ref={containerRef}
          viewBox="0 0 400 400" 
          className="w-full max-w-[420px] aspect-square cursor-crosshair touch-none select-none"
          onMouseMove={(e) => e.buttons === 1 && handleInteraction(e)}
          onMouseDown={handleInteraction}
          onTouchMove={handleInteraction}
        >
          <defs>
            <marker id="arrowhead" markerWidth="10" markerHeight="7" refX="9" refY="3.5" orient="auto">
              <polygon points="0 0, 10 3.5, 0 7" fill="currentColor" />
            </marker>
          </defs>

          {/* Transportador (Background Protractor) */}
          <circle cx="200" cy="200" r="180" fill="rgba(0,0,0,0.02)" stroke="rgba(0,0,0,0.1)" strokeWidth="1" />
          {[...Array(36)].map((_, i) => {
            const deg = i * 10;
            const rad = deg * Math.PI / 180;
            const x1 = 200 + 170 * Math.cos(rad);
            const y1 = 200 - 170 * Math.sin(rad);
            const x2 = 200 + 180 * Math.cos(rad);
            const y2 = 200 - 180 * Math.sin(rad);
            return (
              <g key={i}>
                <line x1={x1} y1={y1} x2={x2} y2={y2} stroke="rgba(0,0,0,0.2)" strokeWidth="1" />
                <text 
                  x={200 + 155 * Math.cos(rad)} 
                  y={200 - 155 * Math.sin(rad)} 
                  fill="rgba(0,0,0,0.3)" 
                  fontSize="8" 
                  textAnchor="middle" 
                  dominantBaseline="middle"
                  className="math-font font-bold"
                >
                  {deg}
                </text>
              </g>
            );
          })}

          {/* Area de Angulo */}
          <path 
            d={`M 200 200 L 280 200 A 80 80 0 ${angle > 180 ? 1 : 0} 0 ${200 + 80 * Math.cos(-angle * Math.PI / 180)} ${200 + 80 * Math.sin(-angle * Math.PI / 180)} Z`}
            fill="rgba(99, 102, 241, 0.15)"
            stroke="rgb(99, 102, 241)"
            strokeWidth="1"
          />

          {/* Rayo Fijo (Lado Inicial) */}
          <line x1="200" y1="200" x2="390" y2="200" stroke="#1e293b" strokeWidth="3" markerEnd="url(#arrowhead)" />

          {/* Rayo Movil (Lado Terminal) */}
          <line 
            x1="200" y1="200" 
            x2={200 + 190 * Math.cos(-angle * Math.PI / 180)} 
            y2={200 + 190 * Math.sin(-angle * Math.PI / 180)} 
            stroke="rgb(168, 85, 247)" 
            strokeWidth="4" 
            markerEnd="url(#arrowhead)"
          />

          <circle cx="200" cy="200" r="5" fill="#1e293b" />
        </svg>
        <p className="mt-6 text-slate-500 text-sm font-bold animate-bounce">Arrastra para mover el ángulo</p>
      </div>

      <div className="space-y-6">
        <div className="glass p-8 rounded-3xl border-indigo-100">
          <div className="flex flex-col gap-1 mb-6">
             <span className="text-7xl font-black text-indigo-900 tracking-tighter">{angle}°</span>
             <span className="text-xl text-indigo-600 font-black uppercase tracking-[0.2em]">{type}</span>
          </div>

          <div className="space-y-6">
            <p className="text-xl text-slate-700 leading-relaxed font-medium italic">
              "{getNarrative(type)}"
            </p>

            <div className="p-5 bg-indigo-50 rounded-2xl border border-indigo-100">
              <h4 className="text-xs font-black text-indigo-700 mb-2 uppercase tracking-widest">Definición Matemática:</h4>
              <ul className="text-sm text-slate-600 space-y-2 font-bold pl-4">
                {type === 'nulo' && <li>θ = 0°</li>}
                {type === 'agudo' && <li>0° &lt; θ &lt; 90°</li>}
                {type === 'recto' && <li>θ = 90°</li>}
                {type === 'obtuso' && <li>90° &lt; θ &lt; 180°</li>}
                {type === 'llano' && <li>θ = 180°</li>}
                {type === 'reflejo' && <li>180° &lt; θ &lt; 360°</li>}
                {type === 'completo' && <li>θ = 360°</li>}
              </ul>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { RefreshCw, Clock } from 'lucide-react';

export const SenseSimulation: React.FC = () => {
  const [angle, setAngle] = useState(0);
  const [direction, setDirection] = useState<'cw' | 'ccw'>('ccw');

  useEffect(() => {
    const interval = setInterval(() => {
      setAngle(prev => {
        const step = direction === 'ccw' ? 2 : -2;
        return (prev + step) % 360;
      });
    }, 30);
    return () => clearInterval(interval);
  }, [direction]);

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-8 items-center bg-white p-10 rounded-[3rem] shadow-sm border border-slate-100">
      <div className="flex flex-col items-center">
        <svg viewBox="0 0 200 200" className="w-64 h-64">
          <circle cx="100" cy="100" r="80" fill="none" stroke="rgba(0,0,0,0.05)" strokeWidth="2" strokeDasharray="5 5" />

          <text x="100" y="100" textAnchor="middle" dominantBaseline="middle" className="text-5xl font-black fill-slate-100">
            {direction === 'ccw' ? '+' : '-'}
          </text>

          <g transform={`rotate(${-angle} 100 100)`}>
             <line x1="100" y1="100" x2="180" y2="100" stroke={direction === 'ccw' ? '#059669' : '#e11d48'} strokeWidth="5" strokeLinecap="round" />
             <path d="M 175 94 L 187 100 L 175 106 Z" fill={direction === 'ccw' ? '#059669' : '#e11d48'} />
          </g>
          <line x1="100" y1="100" x2="180" y2="100" stroke="#1e293b" strokeWidth="2" opacity="0.1" />
        </svg>
      </div>

      <div className="space-y-6">
        <div className="flex flex-col gap-4">
          <button 
            onClick={() => setDirection('ccw')}
            className={`p-6 rounded-2xl flex items-center gap-4 transition-all border-2 ${direction === 'ccw' ? 'bg-emerald-50 border-emerald-500 shadow-md' : 'bg-white border-slate-100 opacity-60'}`}
          >
            <div className={`p-3 rounded-xl ${direction === 'ccw' ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-400'}`}>
              <RefreshCw />
            </div>
            <div className="text-left">
              <p className={`font-black uppercase text-xs tracking-widest ${direction === 'ccw' ? 'text-emerald-700' : 'text-slate-400'}`}>Antihorario (POSITIVO)</p>
              <p className="text-xs text-slate-500 font-medium">Sentido matemático estándar.</p>
            </div>
          </button>

          <button 
            onClick={() => setDirection('cw')}
