    const subModules = [
      { 
        title: "¿Qué es un ángulo?", 
        content: <AngleExplorer />,
        narrative: "Descubre la naturaleza de la apertura entre dos rayos." 
      },
      { 
        title: "Medición y Sentido", 
        content: <SenseSimulation />,
        narrative: "El giro positivo contra el giro negativo. ¡Es cuestión de perspectiva!"
      },
      { 
        title: "El Radián", 
        content: <RadianVisualizer />,
        narrative: "La medida natural del círculo. ¡Aquí Pi (π) es el rey!"
      },
      { 
        title: "Conversión", 
        content: <Converter />,
        narrative: "Aprende a traducir de grados a radianes con precisión."
      },
      { 
        title: "Arco y Sector", 
        content: <ArcAndSector />,
        narrative: "Mide recorridos circulares y áreas de porciones del círculo."
      }
    ];

    return (
      <div className="min-h-screen flex flex-col">
        <header className="p-4 md:p-8 glass-vibrant border-b border-slate-200 flex items-center justify-between sticky top-0 z-50">
           <button onClick={() => setScreen('menu')} className="flex items-center gap-2 text-slate-900 hover:text-purple-600 transition-colors font-black uppercase text-xs md:text-sm tracking-widest group">
             <ChevronLeft strokeWidth={4} className="group-hover:-translate-x-1 transition-transform" /> VOLVER
           </button>
           <div className="flex flex-col items-center">
             <h2 className="text-base md:text-2xl font-black text-purple-700 tracking-tight uppercase">Módulo 1: Ángulos</h2>
             <span className="text-[8px] md:text-[10px] text-slate-500 uppercase tracking-[0.4em] font-black">Fundamentos de Giro</span>
           </div>
           <div className="w-10 h-10 md:w-14 md:h-14 rounded-xl md:rounded-2xl bg-gradient-to-br from-purple-600 to-blue-600 flex items-center justify-center text-white shadow-lg">
             <BrainCircuit size={24} />
           </div>
        </header>

        <main className="flex-1 p-4 md:p-12 max-w-7xl mx-auto w-full space-y-12 pb-48">
           <Teacher message={subModules[activeSubModule].narrative} />

           <div className="space-y-12">
              <div className="flex items-center gap-4 overflow-x-auto pb-6 no-scrollbar snap-x scroll-smooth">
                {subModules.map((sm, idx) => (
                  <button
                    key={idx}
                    onClick={() => setActiveSubModule(idx)}
                    className={`px-8 md:px-12 py-4 md:py-5 rounded-2xl md:rounded-[2rem] text-[10px] md:text-sm font-black uppercase tracking-widest transition-all border-4 snap-center whitespace-nowrap ${
                      activeSubModule === idx 
                        ? 'bg-blue-600 border-blue-400 text-white shadow-2xl scale-105 z-10' 
                        : 'bg-white border-slate-200 text-slate-400 hover:border-blue-200'
                    }`}
                  >
                    {idx + 1}. {sm.title}
                  </button>
                ))}
              </div>

              <div className="mt-8">
                {subModules[activeSubModule].content}
              </div>
           </div>
           <FooterCredits />
        </main>

        <footer className="fixed bottom-0 left-0 right-0 p-4 md:p-8 glass-vibrant border-t-2 border-slate-200 flex justify-between items-center z-40">
            <button 
              disabled={activeSubModule === 0}
              onClick={() => setActiveSubModule(prev => prev - 1)}
              className="p-3 md:p-5 rounded-full disabled:opacity-20 hover:bg-slate-100 transition-colors text-purple-600"
            >
              <ChevronLeft strokeWidth={4} className="w-8 h-8 md:w-12 md:h-12" />
            </button>
            <div className="text-center hidden lg:block">
              <span className="text-xs uppercase tracking-[0.5em] text-slate-900 font-black">Nivel de Maestría</span>
              <div className="flex gap-4 mt-4">
                {subModules.map((_, i) => (
                  <div key={i} className={`h-4 w-20 rounded-full transition-all duration-700 ${i <= activeSubModule ? 'bg-gradient-to-r from-purple-600 to-blue-600 shadow-lg' : 'bg-slate-200'}`} />
                ))}
              </div>
            </div>
            {activeSubModule < subModules.length - 1 ? (
              <button 
                onClick={() => setActiveSubModule(prev => prev + 1)}
                className="bg-purple-600 text-white px-8 md:px-14 py-4 md:py-6 rounded-2xl md:rounded-3xl font-black uppercase tracking-widest text-[10px] md:text-sm flex items-center gap-2 md:gap-4 hover:bg-blue-600 transition-all shadow-2xl"
              >
                AVANZAR <ChevronRight strokeWidth={4} />
              </button>
            ) : (
              <button 
                onClick={() => setScreen('final')}
                className="bg-emerald-600 text-white px-8 md:px-14 py-4 md:py-6 rounded-2xl md:rounded-3xl font-black uppercase tracking-widest text-[10px] md:text-sm flex items-center gap-2 md:gap-4 hover:bg-emerald-700 transition-all shadow-2xl"
              >
                ¡FINALIZAR! <Award strokeWidth={4} />
              </button>
            )}
        </footer>
      </div>
    );
  };

  const renderFinal = () => (
    <div className="min-h-screen flex flex-col items-center justify-center p-8 bg-slate-50">
      <div className="max-w-4xl text-center space-y-12 md:space-y-16">
        <Teacher message="¡Misión cumplida! Has completado la primera etapa de este viaje. El universo es un poco más comprensible hoy para ti." />

        <div className="bg-white p-8 md:p-12 rounded-3xl md:rounded-[3rem] border-4 border-purple-500 shadow-2xl scale-100 md:scale-110">
           <Award size={80} className="text-purple-600 mx-auto mb-4 md:mb-6" />
           <h2 className="text-2xl md:text-4xl font-black text-slate-900 mb-2 md:mb-4">¡Maestro de Ángulos!</h2>
           <p className="text-slate-500 font-black uppercase tracking-widest text-[10px] md:text-sm">Logro Desbloqueado</p>
        </div>

        <button 
          onClick={() => { setScreen('welcome'); setActiveSubModule(0); }}
          className="bg-slate-900 text-white px-10 md:px-14 py-4 md:py-6 rounded-2xl md:rounded-3xl text-[10px] md:text-sm uppercase tracking-[0.5em] font-black hover:bg-purple-600 transition-all shadow-xl"
        >
          VOLVER AL INICIO
        </button>

        <FooterCredits />
      </div>
    </div>
  );

  return (
    <div className="text-slate-900 selection:bg-purple-200 selection:text-purple-900">
      {screen === 'welcome' && renderWelcome()}
      {screen === 'menu' && renderMenu()}
      {screen === 'module1' && renderModule1()}
      {screen === 'final' && renderFinal()}
    </div>
  );
};

export default App;
